def choose_move(observation):
    # Defensive defaults
    # Try to infer a simple robust strategy that works across resource_collection,
    # pursuit_evasion, and territory_control observations without relying on
    # any specific game internals beyond common fields.
    # We use safe fallbacks and small-lookahead style: favor staying close to center
    # and toward any positive signal in observation keys if present.

    # Helper to safely read a key as int tuple or default
    def safe_int_tuple(key, default=(0, 0)):
        val = observation.get(key)
        if isinstance(val, (list, tuple)) and len(val) >= 2:
            try:
                return int(val[0]), int(val[1])
            except Exception:
                return default
        return default

    # Center-based neutral default
    center_dxdy = (0, 0)

    # Common signals (defensively read)
    # nearest_enemy_delta if present
    ner = observation.get("nearest_enemy_delta")
    if isinstance(ner, (list, tuple)) and len(ner) >= 2:
        try:
            ner_dx, ner_dy = int(ner[0]), int(ner[1])
        except Exception:
            ner_dx, ner_dy = 0, 0
    else:
        ner_dx, ner_dy = 0, 0

    # resource_delta - desire to move toward resources
    res = observation.get("resource_delta")
    if isinstance(res, (list, tuple)) and len(res) >= 2:
        try:
            res_dx, res_dy = int(res[0]), int(res[1])
        except Exception:
            res_dx, res_dy = 0, 0
    else:
        res_dx, res_dy = 0, 0

    # territory_status - if there is friendly control pressure
    terr = observation.get("territory_pressure")
    if isinstance(terr, (list, tuple)) and len(terr) >= 2:
        try:
            terr_dx, terr_dy = int(terr[0]), int(terr[1])
        except Exception:
            terr_dx, terr_dy = 0, 0
    else:
        terr_dx, terr_dy = 0, 0

    # Simple heuristic:
    # - If there is resource signal, bias toward resources.
    # - If enemy nearby (ner non-zero), bias away from enemy.
    # - If territory_pressure positive, bias toward supportive direction.
    # - Otherwise stay near center.

    dx = 0
    dy = 0

    if res_dx != 0 or res_dy != 0:
        dx += res_dx
        dy += res_dy
    if ner_dx != 0 or ner_dy != 0:
        # move away from enemy: opposite direction
        dx -= ner_dx
        dy -= ner_dy
    if terr_dx != 0 or terr_dy != 0:
        dx += terr_dx
        dy += terr_dy

    # Clamp to -1..1
    if dx > 1:
        dx = 1
    if dx < -1:
        dx = -1
    if dy > 1:
        dy = 1
    if dy < -1:
        dy = -1

    # If no directive, default toward center
    if dx == 0 and dy == 0:
        dx, dy = center_dxdy

    return [dx, dy]

